INSERT INTO `email_templates` (`id`,`business_profile_id`,`name`,`category`,`subject`,`preheader`,`body`,`body_html`,`body_text`,`followup_stage`,`active`,`created_at`,`updated_at`) VALUES
(1,1,'Initial Outreach - Skincare/Cosmetic Formulators','Skincare / cosmetic formulators','Peptide sourcing support for {{company_name}}','MOQ flexibility, documentation support, and batch transparency for skincare formulation buyers.','Hello {{contact_name}},\n\nI am reaching out from {{brand_name}}. {{brand_name}} supports peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.\n\nFor skincare and cosmetic formulation teams, we focus on practical sourcing conversations, documentation readiness, and commercially clear follow-up.\n\nIf {{company_name}} is reviewing supply options, we would be glad to share next steps.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">I am reaching out from {{brand_name}}. {{brand_name}} supports peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.</p><p style="margin:0 0 16px;">For skincare and cosmetic formulation teams, we focus on practical sourcing conversations, documentation readiness, and commercially clear follow-up.</p><p style="margin:0;">If {{company_name}} is reviewing supply options, we would be glad to share next steps.</p>','Hello {{contact_name}},\n\nI am reaching out from {{brand_name}}. {{brand_name}} supports peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.\n\nFor skincare and cosmetic formulation teams, we focus on practical sourcing conversations, documentation readiness, and commercially clear follow-up.\n\nIf {{company_name}} is reviewing supply options, we would be glad to share next steps.\n\n{{default_signature}}',0,1,'2026-05-12 04:31:27','2026-05-12 04:55:00'),
(2,1,'Initial Outreach - Ingredient Distributors','Ingredient distributors','Documented peptide sourcing coordination for {{company_name}}','A professional supplier introduction for distribution-focused teams.','Hello {{contact_name}},\n\n{{brand_name}} supports peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.\n\nFor ingredient distribution teams, we focus on clear commercial communication, documentation alignment, and sourcing continuity.\n\nIf {{company_name}} is evaluating peptide supply partners, we can share sourcing details and RFQ next steps.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">{{brand_name}} supports peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.</p><p style="margin:0 0 16px;">For ingredient distribution teams, we focus on clear commercial communication, documentation alignment, and sourcing continuity.</p><p style="margin:0;">If {{company_name}} is evaluating peptide supply partners, we can share sourcing details and RFQ next steps.</p>','Hello {{contact_name}},\n\n{{brand_name}} supports peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.\n\nFor ingredient distribution teams, we focus on clear commercial communication, documentation alignment, and sourcing continuity.\n\nIf {{company_name}} is evaluating peptide supply partners, we can share sourcing details and RFQ next steps.\n\n{{default_signature}}',0,1,'2026-05-12 04:31:27','2026-05-12 04:55:00'),
(3,1,'Initial Outreach - Contract Manufacturers','Contract manufacturers','Supply coordination support for {{company_name}}','{{brand_name}} support for planning MOQ, documentation, and sourcing fit.','Hello {{contact_name}},\n\nI am contacting you from {{brand_name}} regarding peptide sourcing support for qualified B2B buyers.\n\nFor contract manufacturing teams, we understand the need for organized supply coordination, MOQ planning, documentation support, and batch transparency before commercial decisions move forward.\n\nIf useful, we can share practical next steps for RFQs and documentation review.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">I am contacting you from {{brand_name}} regarding peptide sourcing support for qualified B2B buyers.</p><p style="margin:0 0 16px;">For contract manufacturing teams, we understand the need for organized supply coordination, MOQ planning, documentation support, and batch transparency before commercial decisions move forward.</p><p style="margin:0;">If useful, we can share practical next steps for RFQs and documentation review.</p>','Hello {{contact_name}},\n\nI am contacting you from {{brand_name}} regarding peptide sourcing support for qualified B2B buyers.\n\nFor contract manufacturing teams, we understand the need for organized supply coordination, MOQ planning, documentation support, and batch transparency before commercial decisions move forward.\n\nIf useful, we can share practical next steps for RFQs and documentation review.\n\n{{default_signature}}',0,1,'2026-05-12 04:31:27','2026-05-12 04:55:00'),
(4,1,'Initial Outreach - Research Supply Buyers','Research supply buyers','Professional sourcing support for {{company_name}}','A practical introduction for qualified research supply buyers.','Hello {{contact_name}},\n\n{{brand_name}} supports qualified B2B research supply buyers with professional sourcing coordination, MOQ flexibility, documentation support, and batch transparency.\n\nOur communication is focused on supply requirements, documentation expectations, and RFQ coordination without exaggerated claims.\n\nIf {{company_name}} is evaluating sourcing options, we would be glad to share availability and next steps.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">{{brand_name}} supports qualified B2B research supply buyers with professional sourcing coordination, MOQ flexibility, documentation support, and batch transparency.</p><p style="margin:0 0 16px;">Our communication is focused on supply requirements, documentation expectations, and RFQ coordination without exaggerated claims.</p><p style="margin:0;">If {{company_name}} is evaluating sourcing options, we would be glad to share availability and next steps.</p>','Hello {{contact_name}},\n\n{{brand_name}} supports qualified B2B research supply buyers with professional sourcing coordination, MOQ flexibility, documentation support, and batch transparency.\n\nOur communication is focused on supply requirements, documentation expectations, and RFQ coordination without exaggerated claims.\n\nIf {{company_name}} is evaluating sourcing options, we would be glad to share availability and next steps.\n\n{{default_signature}}',0,1,'2026-05-12 04:31:27','2026-05-12 04:55:00'),
(5,1,'Follow-Up 1','Other','Following up from {{brand_name}}','A short follow-up on the earlier sourcing introduction.','Hello {{contact_name}},\n\nI wanted to follow up on my previous note from {{brand_name}}.\n\nWe support peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.\n\nIf this is relevant for {{company_name}}, I can share documentation expectations or RFQ next steps.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">I wanted to follow up on my previous note from {{brand_name}}.</p><p style="margin:0 0 16px;">We support peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.</p><p style="margin:0;">If this is relevant for {{company_name}}, I can share documentation expectations or RFQ next steps.</p>','Hello {{contact_name}},\n\nI wanted to follow up on my previous note from {{brand_name}}.\n\nWe support peptide sourcing with MOQ flexibility, documentation support, batch transparency, and supply coordination for qualified B2B buyers.\n\nIf this is relevant for {{company_name}}, I can share documentation expectations or RFQ next steps.\n\n{{default_signature}}',1,1,'2026-05-12 04:31:27','2026-05-12 04:55:00'),
(6,1,'Follow-Up 2','Other','Closing the loop from {{brand_name}}','A final respectful follow-up with a clear opt-out path.','Hello {{contact_name}},\n\nI am closing the loop on my previous outreach.\n\nIf peptide sourcing support, documentation alignment, MOQ flexibility, or batch transparency becomes relevant for {{company_name}}, {{brand_name}} would be glad to help coordinate the conversation.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">I am closing the loop on my previous outreach.</p><p style="margin:0;">If peptide sourcing support, documentation alignment, MOQ flexibility, or batch transparency becomes relevant for {{company_name}}, {{brand_name}} would be glad to help coordinate the conversation.</p>','Hello {{contact_name}},\n\nI am closing the loop on my previous outreach.\n\nIf peptide sourcing support, documentation alignment, MOQ flexibility, or batch transparency becomes relevant for {{company_name}}, {{brand_name}} would be glad to help coordinate the conversation.\n\n{{default_signature}}',2,1,'2026-05-12 04:31:27','2026-05-12 04:55:00'),
(7,1,'RFQ Confirmation','Other','We received your {{brand_name}} RFQ','Your RFQ is in and {{brand_name}} will review the sourcing details.','Hello {{contact_name}},\n\nThank you for contacting {{brand_name}}. We received your RFQ details and will review the request for sourcing fit, documentation expectations, MOQ support, and supply coordination next steps.\n\nOur team will follow up using the contact details provided.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">Thank you for contacting {{brand_name}}. We received your RFQ details and will review the request for sourcing fit, documentation expectations, MOQ support, and supply coordination next steps.</p><p style="margin:0;">Our team will follow up using the contact details provided.</p>','Hello {{contact_name}},\n\nThank you for contacting {{brand_name}}. We received your RFQ details and will review the request for sourcing fit, documentation expectations, MOQ support, and supply coordination next steps.\n\nOur team will follow up using the contact details provided.\n\n{{default_signature}}',9,1,'2026-05-12 04:31:27','2026-05-12 04:55:00'),
(8,1,'Quote Follow-Up','Other','Following up on your {{brand_name}} quote','A practical follow-up after a quote or sourcing discussion.','Hello {{contact_name}},\n\nI wanted to follow up on the quote or sourcing discussion with {{brand_name}}.\n\nIf you have questions about MOQ planning, documentation, batch transparency, or next steps, we would be glad to help.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">I wanted to follow up on the quote or sourcing discussion with {{brand_name}}.</p><p style="margin:0;">If you have questions about MOQ planning, documentation, batch transparency, or next steps, we would be glad to help.</p>','Hello {{contact_name}},\n\nI wanted to follow up on the quote or sourcing discussion with {{brand_name}}.\n\nIf you have questions about MOQ planning, documentation, batch transparency, or next steps, we would be glad to help.\n\n{{default_signature}}',3,1,'2026-05-12 04:31:27','2026-05-12 04:55:00'),
(9,1,'Generic - Initial B2B outreach','Other','Professional B2B introduction from {{brand_name}}','A concise introduction for qualified business outreach.','Hello {{contact_name}},\n\nI am reaching out from {{brand_name}}. {{business_tagline}}\n\nWe support professional {{industry}} conversations with clear coordination, practical next steps, and transparent business communication.\n\nIf this is relevant for {{company_name}}, I would be glad to share more details.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">I am reaching out from {{brand_name}}. {{business_tagline}}</p><p style="margin:0 0 16px;">We support professional {{industry}} conversations with clear coordination, practical next steps, and transparent business communication.</p><p style="margin:0;">If this is relevant for {{company_name}}, I would be glad to share more details.</p>','Hello {{contact_name}},\n\nI am reaching out from {{brand_name}}. {{business_tagline}}\n\nWe support professional {{industry}} conversations with clear coordination, practical next steps, and transparent business communication.\n\nIf this is relevant for {{company_name}}, I would be glad to share more details.\n\n{{default_signature}}',0,1,'2026-05-12 04:55:00','2026-05-12 04:55:00'),
