(11,1,'Generic - Product supplier outreach','Other','Supplier coordination from {{brand_name}}','Clear product-supply coordination for B2B buyers.','Hello {{contact_name}},\n\n{{brand_name}} supports B2B product and supply conversations with clear documentation, practical coordination, and professional follow-up.\n\nIf {{company_name}} is reviewing supplier options, we can share availability, commercial details, and next steps.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">{{brand_name}} supports B2B product and supply conversations with clear documentation, practical coordination, and professional follow-up.</p><p style="margin:0;">If {{company_name}} is reviewing supplier options, we can share availability, commercial details, and next steps.</p>','Hello {{contact_name}},\n\n{{brand_name}} supports B2B product and supply conversations with clear documentation, practical coordination, and professional follow-up.\n\nIf {{company_name}} is reviewing supplier options, we can share availability, commercial details, and next steps.\n\n{{default_signature}}',0,1,'2026-05-12 04:55:00','2026-05-12 04:55:00'),
