(13,1,'Generic - Follow-up 2','Other','Closing the loop from {{brand_name}}','A final respectful follow-up.','Hello {{contact_name}},\n\nI am closing the loop on my previous outreach.\n\nIf this becomes relevant for {{company_name}}, {{brand_name}} would be glad to help with a professional B2B conversation.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">I am closing the loop on my previous outreach.</p><p style="margin:0;">If this becomes relevant for {{company_name}}, {{brand_name}} would be glad to help with a professional B2B conversation.</p>','Hello {{contact_name}},\n\nI am closing the loop on my previous outreach.\n\nIf this becomes relevant for {{company_name}}, {{brand_name}} would be glad to help with a professional B2B conversation.\n\n{{default_signature}}',2,1,'2026-05-12 04:55:00','2026-05-12 04:55:00'),
(14,1,'Generic - RFQ confirmation','Other','We received your request for {{brand_name}}','Your request is in and the team will review it shortly.','Hello {{contact_name}},\n\nThank you for contacting {{brand_name}}. We received your request and will review the details before following up.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0;">Thank you for contacting {{brand_name}}. We received your request and will review the details before following up.</p>','Hello {{contact_name}},\n\nThank you for contacting {{brand_name}}. We received your request and will review the details before following up.\n\n{{default_signature}}',9,1,'2026-05-12 04:55:00','2026-05-12 04:55:00'),
(15,1,'Generic - Quote follow-up','Other','Following up on your {{brand_name}} quote','A short follow-up after a quote or pricing conversation.','Hello {{contact_name}},\n\nI wanted to follow up on the quote conversation with {{brand_name}}.\n\nIf you have questions about scope, timing, or next steps, we would be glad to help.\n\n{{default_signature}}','<p style="margin:0 0 16px;">Hello {{contact_name}},</p><p style="margin:0 0 16px;">I wanted to follow up on the quote conversation with {{brand_name}}.</p><p style="margin:0;">If you have questions about scope, timing, or next steps, we would be glad to help.</p>','Hello {{contact_name}},\n\nI wanted to follow up on the quote conversation with {{brand_name}}.\n\nIf you have questions about scope, timing, or next steps, we would be glad to help.\n\n{{default_signature}}',3,1,'2026-05-12 04:55:00','2026-05-12 04:55:00'),
