INSERT INTO `email_templates` (`business_profile_id`,`name`,`category`,`subject`,`preheader`,`body`,`body_html`,`body_text`,`followup_stage`,`active`,`created_at`,`updated_at`) VALUES
(1,'Initial Outreach - Skincare/Cosmetic Formulators','Skincare / cosmetic formulators','A practical peptide sourcing partner for {{company_name}}','MOQ flexibility, documentation support, and clear coordination for formulation teams.','Hello {{contact_name}},\n\nI am reaching out from {{brand_name}} because {{brand_name}} supports qualified B2B peptide sourcing conversations with a clear commercial process.\n\nFor formulation teams, we focus on practical next steps around MOQ flexibility, documentation support, batch transparency, and sourcing coordination.\n\nHow {{brand_name}} can support:\n- MOQ flexibility support for early-stage or scaling programs\n- Documentation support for internal technical review\n- Batch transparency and qualified B2B supply communication\n\nIf this is relevant for {{company_name}}, we would be glad to discuss current priorities and next steps.\n\n{{default_signature}}','<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">I am reaching out from {{brand_name}} because {{brand_name}} supports qualified B2B peptide sourcing conversations with a clear commercial process.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">For formulation teams, we focus on practical next steps around MOQ flexibility, documentation support, batch transparency, and sourcing coordination.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">How {{brand_name}} Can Support</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top\" widt